for p in (GATE, WORK):
    p.mkdir(parents=True, exist_ok=True)

MSPRED_DIR = Path("/content/ms-pred")
MSPRED_COMMIT = "708148c2a8eb0c32120644436fefd2fe90cd2214"     # pinned: the commit the spec was written against
